(function(root){
'use strict';
const V=root.QuantHardwareView||(typeof require==='function'?require('./hardware-view.js'):null);
const E=root.QuantExecution||(typeof require==='function'?require('./execution-model.js'):null);
const A=root.QuantMotion||(typeof require==='function'?require('./motion-view.js'):null);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function tensorButton(id,label,extra=''){return `<button class="tensor-link" data-inspect="${esc(id)}" ${extra}>${esc(label)}</button>`;}
function locationBox(id,title,frame,snapshot,selected){
 const isUnit=['cpu','cuda','tensor'].includes(id),active=frame.unit===id;
 const source=frame.from===id,dest=frame.to===id,changed=new Set(frame.changes.filter(c=>c.after).map(c=>c.after.key));
 const cells=Object.values(snapshot.cells).filter(c=>c.loc===id);
 const released=frame.changes.filter(c=>!c.after&&c.before.loc===id&&!snapshot.cells[c.before.key]).map(c=>c.before);
 const reading=c=>(frame.entities.includes(c.entity)&&(frame.from===id||(frame.unit&&id==='registers')));
 let status=source&&dest?'Convert':source?'Source':dest?'Destination':active?'Active':released.length?'Release':cells.length?'Retained':'Idle';
 if(frame.unit==='sm'&&id==='tensor')status='Kernel-dependent';
 const computeNote=id==='cpu'?'Tokenizer / runtime control':id==='cuda'?'Elementwise / reductions / conversion':'Matrix multiply-accumulate';
 const data=c=>`<button class="tensor-cell ${selected===c.entity?'is-selected':''} ${changed.has(c.key)?'is-changed':''} ${reading(c)?'is-read':''}" data-inspect="${esc(c.entity)}" data-cell="${esc(c.key)}" aria-label="Inspect ${esc(c.label)}, ${c.dtype}, ${esc(E.locations[id])}"><span class="tensor-label">${A.icon(c.entity==='W'||c.entity==='params'?'weights':c.loc==='kv'?'cache':'tensor','tensor-glyph')}${esc(c.label)}</span>${V.badge(c.dtype)}${id==='kv'?`<small>${esc(c.note)}</small>`:''}</button>`;
 const ghosts=released.length?`<div class="released-copies">${released.map(c=>`<button class="released-tile" data-inspect="${esc(c.entity)}">${A.icon('release')}<span>${esc(c.label)}</span>${V.badge(c.dtype)}<small>Released copy</small></button>`).join('')}</div>`:'';
 const content=isUnit?`<div class="compute-state">${frame.unit==='sm'&&id==='tensor'?'Attention dot-product mapping depends on the kernel':active?esc(frame.title):'No active operation'}</div><p class="memory-node-note">${computeNote}</p>${cells.length?`<div class="tensor-cells">${cells.map(data).join('')}</div>`:''}`:cells.length?`<div class="tensor-cells">${cells.map(data).join('')}</div>`:'<p class="empty-location">No live buffer in this snapshot</p>';
 const note=id==='l2'?'Hardware-managed tile view; replacement is abstracted.':id==='shared'?'Optional, kernel-dependent staging.':id==='registers'?'Working tiles and scalar values; thread-local allocation is abstracted.':'';
 return `<section class="memory-node ${source?'is-source':''} ${dest?'is-dest':''} ${active?'is-compute':''} ${released.length?'is-release':''} ${frame.kind==='Initialize'&&dest?'is-initialize':''} ${isUnit?'compute-unit':''}" data-memory="${id}" aria-label="${esc(E.locations[id])}"><header><h4>${A.icon(A.locationIcons[id])}${esc(title)}</h4><span class="memory-status">${active?'<i class="activity-dot"></i>':''}${status}</span></header>${content}${ghosts}${note?`<p class="memory-node-note">${note}</p>`:''}</section>`;
}
function diagram(model,frame,snapshot,selected){
 const box=(id,title)=>locationBox(id,title,frame,snapshot,selected);
 return `<div class="hardware-board" id="hardware-board"><svg id="transfer-overlay" aria-hidden="true"></svg><section class="hardware-region host-group"><h3>${A.icon('cpu')}Host</h3><div class="host-grid">${box('ssd','SSD')}${box('host','CPU DRAM')}${box('cpu','CPU')}</div></section><section class="hardware-region gpu-group"><div class="region-heading"><h3>${A.icon('cpu')}GPU device</h3><span>Logical hierarchy · one illustrative SM</span></div><div class="device-grid"><section class="hardware-region dram-group"><h3>${A.icon('memory')}GPU DRAM <small>HBM / GDDR</small></h3>${box('weights','Model weights')}${box('activations','Activations')}${box('kv','KV cache')}</section><section class="hardware-region die-group"><h3>${A.icon('cpu')}GPU die · on-chip</h3>${box('l2','L2 cache')}<section class="hardware-region sm-group ${frame.unit&&frame.unit!=='cpu'?'sm-active':''}"><h3>${A.icon('cpu')}Streaming Multiprocessor <small>(SM)</small></h3><div class="kernel-annotation ${frame.unit==='sm'&&frame.kind==='Compute'?'is-active':''}" data-memory="attention"><span>${A.icon('tensor')}Attention kernel</span><small>${frame.unit==='sm'&&frame.kind==='Compute'?esc(frame.title):'CUDA / Tensor mapping depends on the kernel'}</small></div><div class="sm-storage">${box('shared','Shared Memory')}${box('registers','Registers')}</div><div class="sm-compute">${box('cuda','CUDA Cores')}${box('tensor','Tensor Cores')}</div></section></section></div></section></div>`;
}
function cellDescription(c){return c?`${V.badge(c.dtype)} <span>${esc(E.locations[c.loc])}</span>${c.note?`<small>${esc(c.note)}</small>`:''}`:'<span class="absent-copy">No live copy at this location</span>';}
function delta(model,frame){
 const groups=new Map();for(const c of frame.changes){const a=c.after||c.before,k=a.entity+'|'+a.loc;if(!groups.has(k))groups.set(k,{entity:a.entity,loc:a.loc});}
 if(!groups.size)return `<p class="unchanged-state">${frame.kind==='Start'?'No change at this boundary. The previous End and this Start use the same complete snapshot.':frame.kind==='End'?'No additional change. All live buffers are ready for the next operator.':'No tensor buffer changes in this control action.'}</p>`;
 const rows=[...groups.values()].map(g=>{const before=Object.values(frame.before.cells).filter(c=>c.entity===g.entity&&c.loc===g.loc),after=Object.values(frame.snapshot.cells).filter(c=>c.entity===g.entity&&c.loc===g.loc);return `<tr><th scope="row">${tensorButton(g.entity,model.entities[g.entity].label)}<small>${esc(E.locations[g.loc])}</small></th><td>${before.length?before.map(cellDescription).join(''):cellDescription(null)}</td><td>${after.length?after.map(cellDescription).join(''):'<span class="released-copy">Released after its last use</span>'}</td></tr>`;}).join('');
 return `<div class="state-delta-scroll"><table class="state-delta"><thead><tr><th>Tensor / location</th><th>Before this action</th><th>After this action</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}
function inspector(model,id,step,cursor){const entity=model.entities[id],frame=model.stages[step].frames[cursor],history=E.history(model,id),now=Object.values(frame.snapshot.cells).filter(c=>c.entity===id);if(!entity)return '';
 return `<div class="tensor-inspector-heading"><div><span class="step-label">Tensor inspector</span><h2>${esc(entity.label)}</h2></div><button data-close-inspector aria-label="Close tensor inspector">Close ×</button></div><p class="tensor-shape mono">${esc(entity.shape)}</p>${entity.note?`<p>${esc(entity.note)}</p>`:''}<div class="inspector-legend"><span>Dtype color:</span>${['FP16','FP32','INT4','INT8','INT32'].map(d=>V.badge(d)).join('')}<span>Location is written explicitly; Copy preserves the source.</span></div><h3>Copies in the current snapshot</h3>${now.length?`<ul class="copy-list">${now.map(c=>`<li>${V.badge(c.dtype)} <strong>${esc(E.locations[c.loc])}</strong><span>${esc(c.label)}</span><small>${esc(c.shape)}${c.note?' · '+esc(c.note):''}</small></li>`).join('')}</ul>`:'<p class="empty-inspector">This tensor has no live copy at the selected point. Its creation, uses and release are listed below.</p>'}${entity.parents.length?`<p class="lineage">${['kc','vc'].includes(id)?'Current append input:':'Derived from'} ${entity.parents.map(p=>tensorButton(p,model.entities[p].label)).join(' + ')}</p>`:''}<h3>Lifecycle in this forward</h3><p class="muted">Select an entry to show that exact action on the hardware model. Conversion changes a working representation; a compute action can create a new derived tensor.</p><ol class="tensor-history">${history.map(h=>{const current=h.stage===step&&h.frame===cursor;const changed=h.changes.filter(c=>c.after);const formats=[...new Set(changed.length?changed.map(c=>c.after.dtype):Object.values(h.before.cells).filter(c=>c.entity===id&&c.loc===(h.from||'registers')).map(c=>c.dtype))];return `<li><button data-jump-step="${h.stage}" data-jump-action="${h.frame}" class="${current?'current-history':''}"><span class="history-order">${String(h.stage+1).padStart(2,'0')}.${h.frame}</span><span><strong>${esc(h.title)}</strong><small>${h.unit?'Execution: '+esc(E.locations[h.unit])+(h.to?' · Output: '+esc(E.locations[h.to]):''):(h.from?esc(E.locations[h.from])+' → ':'')+(h.to?esc(E.locations[h.to]):esc(h.kind))}</small><span class="history-formats">${formats.map(d=>V.badge(d)).join('')}</span></span><span aria-hidden="true">↗</span></button></li>`;}).join('')}</ol>`;
}
root.QuantExecutionView={diagram,delta,inspector,tensorButton,esc};if(typeof module!=='undefined')module.exports=root.QuantExecutionView;
})(typeof globalThis!=='undefined'?globalThis:this);
